import XCTest
import CoreLocation
@testable import ManhuntCrews

final class ClockTests: XCTestCase {
    func testRunningClockUsesServerTimestamps() {
        let since = Date(timeIntervalSince1970: 1_000)
        let c = ClockView(accumulatedMs: 60_000, runningSince: since)
        XCTAssertEqual(c.elapsedMs(at: since.addingTimeInterval(30)), 90_000, accuracy: 0.5)
        // Device clock changes don't matter: only the server "now" passed in counts.
        XCTAssertEqual(c.elapsedMs(at: since), 60_000, accuracy: 0.5)
    }

    func testFrozenClockDoesNotAdvance() {
        let c = ClockView(accumulatedMs: 26 * 60_000, runningSince: nil)
        XCTAssertEqual(c.elapsedMs(at: Date().addingTimeInterval(9999)), 26 * 60_000)
    }

    func testServerClockAnchorsToTheMonotonicClock() {
        let clock = ServerClock()
        let server = Date(timeIntervalSince1970: 2_000_000_000)
        clock.observe(serverTime: server, rtt: 0.2)
        let now = clock.now()
        XCTAssertEqual(now.timeIntervalSince(server), 0.1, accuracy: 0.5)
    }

    func testServerClockKeepsCountingAcrossSleep() {
        var t: TimeInterval = 500
        let clock = ServerClock(elapsed: { t })
        let server = Date(timeIntervalSince1970: 2_000_000_000)
        clock.observe(serverTime: server, rtt: 0.2)
        t += 40 * 60  // phone locked in a pocket for 40 minutes
        XCTAssertEqual(clock.now().timeIntervalSince(server), 40 * 60 + 0.1, accuracy: 0.01)
        // The old anchor is stale after the gap, so even a slow first response re-anchors.
        clock.observe(serverTime: server.addingTimeInterval(40 * 60 + 5), rtt: 2)
        XCTAssertEqual(clock.now().timeIntervalSince(server), 40 * 60 + 6, accuracy: 0.01)
    }

    func testFormatting() {
        XCTAssertEqual(Fmt.clock(26 * 60), "26:00")
        XCTAssertEqual(Fmt.clock(3725), "1:02:05")
        XCTAssertEqual(Fmt.clock(-5), "0:00")
        XCTAssertEqual(Fmt.distance(1609.344, units: "MILES"), "1.00 mi")
        XCTAssertEqual(Fmt.distance(2500, units: "KILOMETERS"), "2.50 km")
    }
}

final class SampleFilterTests: XCTestCase {
    private let base = CLLocationCoordinate2D(latitude: 39.7392, longitude: -104.9903)
    private func offset(_ meters: Double) -> CLLocationCoordinate2D {
        .init(latitude: base.latitude + meters / 111_195, longitude: base.longitude)
    }

    func testKeepsFirstAndThrottles() {
        var f = SampleFilter()
        let t0 = Date()
        XCTAssertTrue(f.shouldKeep(timestamp: t0, coordinate: base, horizontalAccuracy: 5, stationary: false))
        XCTAssertFalse(f.shouldKeep(timestamp: t0.addingTimeInterval(2), coordinate: offset(20), horizontalAccuracy: 5, stationary: false), "under min interval")
        XCTAssertTrue(f.shouldKeep(timestamp: t0.addingTimeInterval(6), coordinate: offset(20), horizontalAccuracy: 5, stationary: false), "moved 20 m after 6 s")
    }

    func testStationaryCadence() {
        var f = SampleFilter()
        let t0 = Date()
        _ = f.shouldKeep(timestamp: t0, coordinate: base, horizontalAccuracy: 5, stationary: true)
        XCTAssertFalse(f.shouldKeep(timestamp: t0.addingTimeInterval(20), coordinate: base, horizontalAccuracy: 5, stationary: true))
        XCTAssertTrue(f.shouldKeep(timestamp: t0.addingTimeInterval(31), coordinate: base, horizontalAccuracy: 5, stationary: true))
    }

    func testRejectsInvalidAndOutOfOrder() {
        var f = SampleFilter()
        let t0 = Date()
        XCTAssertFalse(f.shouldKeep(timestamp: t0, coordinate: base, horizontalAccuracy: -1, stationary: false))
        XCTAssertFalse(f.shouldKeep(timestamp: t0, coordinate: base, horizontalAccuracy: 500, stationary: false))
        XCTAssertTrue(f.shouldKeep(timestamp: t0, coordinate: base, horizontalAccuracy: 5, stationary: false))
        XCTAssertFalse(f.shouldKeep(timestamp: t0.addingTimeInterval(-10), coordinate: offset(50), horizontalAccuracy: 5, stationary: false))
    }

    func testMovingMaxIntervalKeepsSlowMovement() {
        var f = SampleFilter()
        let t0 = Date()
        _ = f.shouldKeep(timestamp: t0, coordinate: base, horizontalAccuracy: 5, stationary: false)
        XCTAssertFalse(f.shouldKeep(timestamp: t0.addingTimeInterval(8), coordinate: offset(3), horizontalAccuracy: 5, stationary: false))
        XCTAssertTrue(f.shouldKeep(timestamp: t0.addingTimeInterval(16), coordinate: offset(6), horizontalAccuracy: 5, stationary: false))
    }
}

final class DecodingTests: XCTestCase {
    /// A seeker view exactly as the backend renders it (generated by backend views.ts):
    /// three crews, two phones on the hiding crew, a released pin and a waiting ping.
    let seekerView = #"""
    {"schemaVersion":2,"uid":"uid-seeker-taylor","sessionId":"sess1","renderedAt":"2026-10-17T20:21:00.000Z","stateVersion":100005,"session":{"title":"Friday Manhunt","scheduledDate":"2026-10-17","status":"LOBBY","isHost":false,"myTeam":"B","completedRoundCount":0,"rules":{"headStartSeconds":600,"pingIntervalSeconds":600,"visiblePingHistoryCount":1,"maxChaseSeconds":null,"confirmationTimeoutSeconds":120,"manualPausesEnabled":true,"maxPingGpsAgeSeconds":60,"maxPingAccuracyMeters":50},"teams":{"A":{"teamId":"teamA","key":"A","name":"Crew A","color":"#1E88E5","roster":[{"personId":"p-morgan","displayName":"Morgan"},{"personId":"p-casey","displayName":"Casey"},{"personId":"p-jules","displayName":"Jules"}],"operators":[{"uid":"uid-hider-morgan","personId":null,"displayName":"hider morgan","isMe":false,"consentGiven":true},{"uid":"uid-hider-casey","personId":null,"displayName":"hider casey","isMe":false,"consentGiven":true}],"isMine":false},"B":{"teamId":"teamB","key":"B","name":"Crew B","color":"#F4511E","roster":[{"personId":"p-taylor","displayName":"Taylor"},{"personId":"p-riley","displayName":"Riley"},{"personId":"p-sam","displayName":"Sam"}],"operators":[{"uid":"uid-seeker-taylor","personId":null,"displayName":"seeker taylor","isMe":true,"consentGiven":true}],"isMine":true},"C":{"teamId":"teamC","key":"C","name":"Crew C","color":"#43A047","roster":[{"personId":"p-alex","displayName":"Alex"}],"operators":[{"uid":"uid-seeker-c-alex","personId":null,"displayName":"seeker c alex","isMe":false,"consentGiven":true}],"isMine":false}},"joinCode":"NIGHTCODE","revoked":false},"round":{"id":"round1","index":1,"state":"CHASE","pausedFromState":null,"myRole":"SEEKING","myTeam":"B","hidingTeam":"A","seekingTeams":["B","C"],"seekMode":"RACE","rules":{"headStartSeconds":600,"pingIntervalSeconds":600,"visiblePingHistoryCount":1,"maxChaseSeconds":null,"confirmationTimeoutSeconds":120,"manualPausesEnabled":true,"maxPingGpsAgeSeconds":60,"maxPingAccuracyMeters":50},"ready":{"A":true,"B":true,"C":true},"roundStartAt":"2026-10-17T20:00:00.000Z","headStartEndsAt":null,"chaseStartAt":"2026-10-17T20:10:00.000Z","headStartClock":{"accumulatedMs":600000,"runningSince":null},"chaseClock":{"accumulatedMs":0,"runningSince":"2026-10-17T20:10:00.000Z"},"nextPingAt":"2026-10-17T20:30:00.000Z","nextPingIndex":2,"waitingPing":{"index":1,"deadline":"2026-10-17T20:20:00.000Z","since":"2026-10-17T20:20:00.000Z"},"timeCapAt":null,"pins":[{"index":0,"scheduledAt":"2026-10-17T20:10:00.000Z","releasedAt":"2026-10-17T20:10:00.000Z","observedAt":"2026-10-17T20:09:47.000Z","latitude":39.74,"longitude":-104.99,"accuracyMeters":8,"ageSeconds":13,"delayed":false}],"pingLog":[{"index":0,"scheduledAt":"2026-10-17T20:10:00.000Z","releasedAt":"2026-10-17T20:10:00.000Z","status":"RELEASED","ageSeconds":13,"accuracyMeters":8,"delayed":false}],"pingCount":1,"pause":null,"pendingPauseRequest":null,"claimByTeam":null,"myClaim":null,"captureRequest":null,"lastClaimOutcome":null,"crewStatus":{"A":{"live":0,"total":2,"state":"NO_SIGNAL","issues":[]},"B":{"live":0,"total":1,"state":"NO_SIGNAL","issues":[]},"C":{"live":0,"total":1,"state":"NO_SIGNAL","issues":[]}},"result":null,"endedAt":null,"phaseGeneration":2},"previousRounds":[],"nextRound":null}
    """#

    func testDecodesThreeCrewSeekerView() throws {
        let v = try JSONCoding.decoder.decode(SessionViewDoc.self, from: Data(seekerView.utf8))
        let r = try XCTUnwrap(v.round)
        XCTAssertEqual(r.state, .CHASE)
        XCTAssertEqual(r.myRole, .SEEKING)
        XCTAssertEqual(r.myTeam, .B)
        XCTAssertEqual(r.seekingTeams, [.B, .C])
        XCTAssertEqual(r.seekMode, .RACE)
        XCTAssertEqual(r.pins.map(\.index), [0])
        XCTAssertEqual(r.waitingPing?.index, 1)
        XCTAssertEqual(r.status(.A)?.total, 2)
        XCTAssertEqual(v.session.teamKeys, [.A, .B, .C])
        XCTAssertEqual(v.session.team(.A)?.operators.count, 2)
        XCTAssertEqual(v.session.team(.B)?.me?.isMe, true)
        XCTAssertTrue(r.isReady(.C))
        let chase = try XCTUnwrap(r.chaseClock)
        let fiveMinIn = try XCTUnwrap(JSONCoding.parseDate("2026-10-17T20:15:00.000Z"))
        XCTAssertEqual(chase.elapsedMs(at: fiveMinIn), 300_000, accuracy: 1)
    }

    func testRulesPatchEncodesExplicitNulls() throws {
        var r = Rules.defaults
        r.visiblePingHistoryCount = nil
        r.maxChaseSeconds = nil
        let json = String(data: try JSONCoding.encoder.encode(RulesPatch(r)), encoding: .utf8)!
        XCTAssertTrue(json.contains("\"visiblePingHistoryCount\":null"))
        XCTAssertTrue(json.contains("\"maxChaseSeconds\":null"))
    }

    func testSetupPatchEncodesCrewRemovalAndPhoneRemovalAsNull() throws {
        let body = SetupPatchBody(title: nil, rules: nil, teams: ["C": .remove, "A": .edit(.init(name: "Owls", roster: nil))], moves: [.init(uid: "u1", teamKey: nil), .init(uid: "u2", teamKey: .B)])
        let json = try JSONSerialization.jsonObject(with: JSONCoding.encoder.encode(body)) as! [String: Any]
        let teams = json["teams"] as! [String: Any]
        XCTAssertTrue(teams["C"] is NSNull)
        XCTAssertEqual((teams["A"] as! [String: Any])["name"] as? String, "Owls")
        let moves = json["moves"] as! [[String: Any]]
        XCTAssertTrue(moves[0]["teamKey"] is NSNull)
        XCTAssertEqual(moves[1]["teamKey"] as? String, "B")
    }

    func testDeepLinks() {
        XCTAssertEqual(DeepLink(url: URL(string: "manhuntcrews://join?code=ABCD2345")!), .join(code: "ABCD2345"))
        XCTAssertEqual(DeepLink(url: URL(string: "manhuntcrews://friend?token=xyz")!), .friend(token: "xyz"))
        XCTAssertNil(DeepLink(url: URL(string: "https://evil.example/join?code=1")!))
        XCTAssertNil(DeepLink(url: URL(string: "manhuntcrews://join")!))
    }
}

final class TeamShufflerTests: XCTestCase {
    struct P: Equatable { let name: String; let phone: Bool }

    func testDealsEvenlyAndGivesEveryCrewAPhoneWhenPossible() {
        let people = (0..<8).map { P(name: "p\($0)", phone: $0 < 3) }
        for _ in 0..<50 {
            let crews = TeamShuffler.deal(people, into: 3) { $0.phone }
            XCTAssertEqual(crews.flatMap { $0 }.count, 8)
            XCTAssertEqual(Set(crews.flatMap { $0 }.map(\.name)).count, 8)
            XCTAssertLessThanOrEqual(crews.map(\.count).max()! - crews.map(\.count).min()!, 1)
            XCTAssertTrue(crews.allSatisfy { $0.contains(where: \.phone) })
        }
    }

    func testTwoPhonesNeverLandOnTheSameCrewWhenTwoCrews() {
        let people = [P(name: "a", phone: true), P(name: "b", phone: true), P(name: "c", phone: false), P(name: "d", phone: false)]
        for _ in 0..<30 {
            let crews = TeamShuffler.deal(people, into: 2) { $0.phone }
            XCTAssertEqual(crews.map { $0.filter(\.phone).count }, [1, 1])
        }
    }
}

final class WarningLabelTests: XCTestCase {
    func testSideWarningsReadAsHidersOrSeekers() {
        XCTAssertEqual("HIDER_GPS_STALE".warningLabel, "Hiders: no recent GPS fix")
